#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10

DEV_HOST="dev.hogar.therandomcollection.co"
PROD_HOST="hogar.therandomcollection.co"
EXPECTED_DEV_API="https://hogar-api-dev.onrender.com"

banner "Hogar · stand up the dev environment (ticket #45, ADR 0010)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "Render reads the Blueprint from main, so hogar-api-dev only exists once"
say "the PR that adds it to render.yaml is merged."
step "Merge the PR for #45 into main first."
if ! confirm "Is it merged?"; then
  warn "Merge it, then run this wizard again."; exit 1
fi
git fetch origin main --quiet
if ! git show origin/main:render.yaml | grep -q "name: hogar-api-dev"; then
  warn "origin/main's render.yaml has no hogar-api-dev yet. Merge first, then re-run."; exit 1
fi
say "${GREEN}✓${RESET} origin/main defines hogar-api-dev."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the dev branch"
say "Render and Vercel deploy dev from a branch called dev. It's disposable and"
say "never merged; we start it at origin/main."
if git ls-remote --exit-code --heads origin dev >/dev/null 2>&1; then
  note "origin/dev already exists; leaving it as it is."
elif confirm "Push origin/main to a new branch origin/dev?"; then
  git push origin origin/main:refs/heads/dev
  say "${GREEN}✓${RESET} origin/dev created."
else
  SKIPPED+=("create the dev branch: git push origin origin/main:refs/heads/dev")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon: the hogar-dev project"
say "A separate project, so nothing configured for dev can ever reach production."
open_url "https://console.neon.tech/app/projects"
step "New project. Name: hogar-dev. Postgres version: 17."
step "Region: AWS Europe Central 1 (Frankfurt), the same as the API."
step "Create. Then Connect → turn Connection pooling OFF."
step "Copy the connection string (ends in ?sslmode=require). Keep it for stage 5."
note "Migrations need the direct connection; the hostname must not contain -pooler."
ask_secret DEV_DATABASE_URL "Paste it here (hidden), for the Reset dev database workflow:"
dev_db_host="${DEV_DATABASE_URL#*@}"; dev_db_host="${dev_db_host%%[/:?]*}"
expected_db_host=$(sed -nE 's/^ *DEV_DATABASE_HOST: *//p' .github/workflows/reset-dev-database.yml)
if [[ "$DEV_DATABASE_URL" != postgresql://* || "$dev_db_host" == *-pooler* ]]; then
  warn "That isn't a direct connection string (postgresql://…, host without -pooler); not saved."
  SKIPPED+=("GitHub secret DEV_DATABASE_URL (hogar-dev's direct connection string)")
else
  set_secret DEV_DATABASE_URL "$DEV_DATABASE_URL"
  if [[ "$dev_db_host" != "$expected_db_host" ]]; then
    warn "Its host, $dev_db_host, isn't the one the reset workflow expects ($expected_db_host)."
    SKIPPED+=("set DEV_DATABASE_HOST in .github/workflows/reset-dev-database.yml to $dev_db_host")
  fi
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Resend: a dev API key"
say "dev gets its own key, so you can revoke it without touching production."
open_url "https://resend.com/api-keys"
step "Create API key. Name: hogar-dev."
step "Permission: Sending access. Domain: hogar.therandomcollection.co only."
step "Copy the key (re_…). It's shown only once. Keep it for stage 5."
note "The sender for stage 5: Hogar dev <dev@hogar.therandomcollection.co>"
pause "Copied? Press Enter"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Render: sync the Blueprint and fill hogar-api-dev"
open_url "https://dashboard.render.com/blueprints"
step "Open Hogar's Blueprint → Manual sync. Render proposes creating hogar-api-dev."
step "Fill the variables it asks for (production's are already set):"
note "    DATABASE_URL      the hogar-dev connection string from stage 3"
note "    GOOGLE_CLIENT_ID  the same Client ID as production"
note "    RESEND_API_KEY    the dev key from stage 4"
note "    EMAIL_FROM        Hogar dev <dev@hogar.therandomcollection.co>"
note "WEB_ORIGIN, WEB_PREVIEW_ORIGIN, COOKIE_SECURE and TRUST_PROXY_HOPS come from render.yaml;"
note "JWT_ACCESS_SECRET and EMAIL_CODE_SECRET are generated."
step "Apply. Wait for the first deploy to go Live (a few minutes)."
step "Copy the service URL shown under its name (https://….onrender.com)."
ask DEV_API_URL "Paste hogar-api-dev's URL:"
DEV_API_URL="${DEV_API_URL%/}"
if [[ "$DEV_API_URL" != "$EXPECTED_DEV_API" ]]; then
  warn "Render gave it $DEV_API_URL, not $EXPECTED_DEV_API."
  SKIPPED+=("point the dev rewrite in apps/web/vercel.json (and its test) at $DEV_API_URL")
fi
if curl -fsS -m 90 "$DEV_API_URL/api/health" | grep -q '"ok"'; then
  say "${GREEN}✓${RESET} $DEV_API_URL/api/health answers ok."
else
  warn "health check didn't answer ok yet: check the deploy logs on Render."
  SKIPPED+=("check $DEV_API_URL/api/health returns {\"status\":\"ok\"}")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel: the dev domain"
open_url "https://vercel.com/dashboard"
step "Open the web project (Root Directory apps/web) → Settings → Domains."
step "Add $DEV_HOST."
step "Choose Connect to an environment → Preview → Git branch: dev. Save."
step "Vercel shows a CNAME record for 'dev.hogar'. Keep that page open."
pause "Domain added? Press Enter"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "DNS: the CNAME for dev"
say "At the registrar for therandomcollection.co, in its DNS settings:"
step "Add a CNAME record. Name/host: dev.hogar. Value: what Vercel shows"
step "(usually cname.vercel-dns.com or a project-specific …vercel-dns-….com)."
step "Back in Vercel's Domains page, wait until $DEV_HOST shows Valid Configuration."
pause "Valid? Press Enter"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Vercel: Google Client ID for Preview, and the old URL's redirect"
say "dev builds as a Preview deployment, so it needs the Client ID too."
step "Settings → Environment Variables → VITE_GOOGLE_CLIENT_ID → Edit."
step "Tick Preview as well as Production (same value). Save."
say ""
say "The old hogar-virid-nine.vercel.app would now be routed to the dev API:"
step "Settings → Domains → hogar-virid-nine.vercel.app → Edit."
step "Redirect to $PROD_HOST, status 308 Permanent Redirect. Save."
note "Leave Deployment Protection on Standard Protection (the default)."
pause "Done? Press Enter"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Google: authorize dev's origin"
open_url "https://console.cloud.google.com/auth/clients"
step "Open Hogar's Web client."
step "Authorized JavaScript origins → Add URI → https://$DEV_HOST"
step "Check https://$PROD_HOST is listed too. Save."
note "New origins can take a few minutes to start working."
pause "Saved? Press Enter"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Deploy and check"
say "Trigger a Vercel deploy of dev. Re-pushing the same commit is a no-op, and"
say "Vercel skips a new branch whose commit it already deployed, so push a new"
say "empty commit on top of origin/main (your branch and files are untouched)."
if confirm "Force-push an empty commit on origin/main onto origin/dev now?"; then
  git fetch origin main --quiet
  trigger=$(git commit-tree "origin/main^{tree}" -p origin/main -m "chore: deploy dev")
  git push origin "$trigger:refs/heads/dev" --force
fi
code=$(curl -s -o /dev/null -w '%{http_code}' -m 20 https://hogar-virid-nine.vercel.app/ || true)
if [[ "$code" == "308" ]]; then
  say "${GREEN}✓${RESET} the old Vercel URL answers 308."
else
  warn "the old Vercel URL answered $code, not 308 (Vercel's login can answer first: check it by hand in a browser)."
  SKIPPED+=("check hogar-virid-nine.vercel.app redirects (308) to $PROD_HOST")
fi
open_url "https://$DEV_HOST"
step "Once the deploy is Ready: sign in with Google on $DEV_HOST."
step "Sign out, then sign in with a code: the email comes from Hogar dev."
step "As a new person you start without a household (an empty database)."
open_url "https://$PROD_HOST"
step "Production still signs in as before."
pause "All good? Press Enter"

finish
}

run_wizard "$@"; exit
